    """
    Try to find the most capable encoding supported by the console.
    slightly modified from the way IPython handles the same issue.
    """
    # First, try to get the encoding from the console.
    # For Windows, we need to try several different ways
    # (depending on whether pyreadline is installed or not)
    # and pick the first one that works.
    # For other platforms, we try to use locale.getpreferredencoding.
    # If that fails, we fall back to sys.getdefaultencoding.
    # Note: we don't use sys.stdout.encoding here, because it's often None
    # even when the console is capable of displaying unicode.
    encoding = None
    if sys.platform == 'win32':
        if 'pyreadline' in sys.modules:
            try:
                import pyreadline.console.iohl as iohl
                encoding = iohl.get_preferred_encoding()
            except ImportError:
                pass
        if encoding is None:
            try:
                import pyreadline.console.ioloop as ioloop
                encoding = ioloop.get_preferred_encoding()
            except ImportError:
                pass
